import pytest
from solution import parse_duration

@pytest.mark.parametrize('s,n', [('45s',45),('2h',7200),('1h30m',5400),('1d2h',93600),('1h 15m 10s',4510),('  3M ',180)])
def test_ok(s, n):
    assert parse_duration(s) == n

@pytest.mark.parametrize('bad', ['', '10', '5x', '1h1h', 'h'])
def test_bad(bad):
    with pytest.raises(ValueError):
        parse_duration(bad)
